package org.sleepwell.app;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
/** Private repeat-rule draft. Only Use returns it; the parent still requires Save alarm. */
public final class AlarmRepeatActivity extends Activity {
 static final int REQUEST=839;private Alarm alarm;private String request,identity,error="",every="3";private AlarmRepeat.Mode mode;private LocalDate anchor;private final Set<Integer> days=new TreeSet<>();private EditText interval;private RecordCalendar calendar;
 static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,AlarmRepeatActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);setResult(RESULT_CANCELED);try{request=getIntent().getStringExtra("request");if(!BackupRuntime.nonce(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));if(alarm.nap!=null||alarm.napInvalid)throw new IllegalArgumentException();identity=AlarmRepeat.identity(alarm);mode=state==null?alarm.repeatRule.mode:AlarmRepeat.Mode.valueOf(state.getString("mode"));anchor=state==null?(alarm.repeatRule.anchor==null?LocalDate.now():alarm.repeatRule.anchor):LocalDate.parse(state.getString("anchor"));every=state==null?Integer.toString(alarm.repeatRule.every==0?3:alarm.repeatRule.every):state.getString("every","3");days.addAll(state==null?alarm.days:AlarmRepeat.days(new JSONArray(state.getString("days","[]"))));error=state==null?(alarm.repeatInvalid?"Saved repeat settings need review. Choose a rule before using it.":""):state.getString("error","");}catch(Exception invalid){finish();return;}render();if(state!=null&&state.containsKey("calendar"))openAnchor(state.getBundle("calendar"));}
 private void keepInput(){if(interval!=null)every=interval.getText().toString();}
 private Alarm candidate()throws JSONException{Alarm copy=Alarm.read(alarm.json());AlarmRepeat rule=mode==AlarmRepeat.Mode.WEEKLY?AlarmRepeat.WEEKLY:mode==AlarmRepeat.Mode.INTERVAL?new AlarmRepeat(mode,intervalValue(),anchor):new AlarmRepeat(mode,0,null);copy.setRepeat(rule);copy.days=new HashSet<>(mode==AlarmRepeat.Mode.INTERVAL?AlarmRepeat.ALL:days);if(copy.date!=null&&!copy.days.isEmpty())throw new IllegalArgumentException("Clear the one-time Run on date before choosing repeat days.");rule.check(copy);if(!AlarmSkips.scheduleKey(copy).equals(AlarmSkips.scheduleKey(alarm)))AlarmSkips.consume(copy);return copy;}
 private int intervalValue(){try{int value=Integer.parseInt(every);if(value<1||value>365)throw new NumberFormatException();return value;}catch(NumberFormatException invalid){throw new IllegalArgumentException("Choose an interval from 1 to 365 days.");}}
 private void render(){keepInput();interval=null;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Repeat rule",this::finish);Design.space(body,16);RecordUi.segments(body,new String[]{"Weekly","Odd","Even","Interval"},mode.ordinal(),n->{keepInput();mode=AlarmRepeat.Mode.values()[n];error="";render();});Design.space(body,18);Design.text(body,switch(mode){case WEEKLY->"Weekly or one-time";case ODD->"Odd ISO weeks";case EVEN->"Even ISO weeks";case INTERVAL->"Every N calendar days";},24,600,Design.INK);Design.space(body,10);
  if(mode==AlarmRepeat.Mode.INTERVAL){Design.text(body,"Choose an anchor date and count forward by calendar days. The anchor is eligible; dates before it are not. Weekday filters do not apply.",14,400,Design.MUTED);Design.space(body,14);Design.text(body,"Repeat every · days (1–365)",15,600,Design.INK);interval=new EditText(this);interval.setContentDescription("Repeat interval days");interval.setSingleLine(true);interval.setInputType(InputType.TYPE_CLASS_NUMBER);interval.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(3)});interval.setText(every);interval.setTextSize(25*Appearance.scale(this));interval.setTypeface(Design.font(this,600));interval.setTextColor(Design.INK);Design.pad(interval,14,12);interval.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));body.addView(interval);Design.space(body,12);Design.item(body,"calendar","Anchor date",anchor.toString(),()->openAnchor(null));Design.button(body,"Refresh occurrence preview",false,()->{keepInput();render();});}
  else{Design.text(body,mode==AlarmRepeat.Mode.WEEKLY?"Choose repeat weekdays. No selected weekdays means one ordinary occurrence.":"ISO weeks start on Monday. Week 1 is the first week with at least four days in the new year. Select at least one weekday. At an ISO-year boundary, weeks 53 and 1 are both odd.",14,400,Design.MUTED);Design.space(body,16);LinearLayout week=Design.row(this);String[] labels={"M","T","W","T","F","S","S"},names={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};for(int n=1;n<=7;n++){int day=n;Button button=dayButton(labels[n-1],days.contains(n),()->{keepInput();if(days.contains(day))days.remove(day);else days.add(day);error="";render();});button.setContentDescription(names[n-1]);button.setSelected(days.contains(n));LinearLayout.LayoutParams bounds=new LinearLayout.LayoutParams(0,Design.dp(this,48),1);bounds.setMargins(Design.dp(this,1),0,Design.dp(this,1),0);week.addView(button,bounds);}body.addView(week);}
  Design.space(body,18);Design.text(body,"Dates follow "+ZoneId.systemDefault().getId()+". Local clock changes follow the alarm’s existing daylight-saving behavior. Sunrise alarms keep their calculated sunrise and selected fallback time.",12,400,Design.MUTED);Design.space(body,12);String projection;try{keepInput();Alarm proposed=candidate();long at=proposed.next(System.currentTimeMillis(),ZoneId.systemDefault());projection=at>0?"Next ordinary occurrence · "+RecordUi.date(at,ZoneId.systemDefault())+" · "+RecordUi.clock(this,at,ZoneId.systemDefault()):"No future occurrence. Review the selected date and exclusions.";}catch(Exception invalid){projection=invalid.getMessage()==null?"Review this rule’s days and interval.":invalid.getMessage();}Design.text(body,projection,14,500,Design.BROWN);Design.space(body,10);Design.text(body,"Calendar adjustments and selected days off apply when the alarm is saved. Current snoozes and ringing alarms are unchanged. Use returns a draft; Save alarm is still required.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,0xffa93919);Design.button(footer,"Use repeat rule",true,this::use);Design.button(footer,"Cancel",false,this::finish);
 }
 private Button dayButton(String label,boolean selected,Runnable action){Button button=new Button(this);button.setStateListAnimator(null);button.setElevation(0);button.setText(label);button.setAllCaps(false);button.setTextSize(15*Appearance.scale(this));button.setTypeface(Design.font(this,600));button.setPadding(0,0,0,0);button.setMinWidth(0);button.setMinimumWidth(0);button.setTextColor(selected?Design.CREAM:Design.BROWN);button.setBackground(Design.touch(this,selected?Design.BROWN:Design.SOFT,24));button.setOnClickListener(view->action.run());return button;}
 private void use(){if(!hasWindowFocus())return;keepInput();try{Alarm selected=candidate();setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("draft",identity).putExtra("rule",AlarmRepeat.encode(selected.repeatRule).toString()).putExtra("days",new JSONArray(new TreeSet<>(selected.days)).toString()));finish();}catch(Exception invalid){error=invalid.getMessage()==null?"Choose a valid repeat rule.":invalid.getMessage();render();}}
 private void openAnchor(Bundle restored){keepInput();if(calendar!=null)calendar.close();calendar=new RecordCalendar(this,"Repeat anchor date",anchor,restored,date->{if(date.getYear()<1970||date.getYear()>9998)error="Choose an anchor year from 1970 to 9998.";else{anchor=date;error="";}render();},null);}
 @Override public void onSaveInstanceState(Bundle state){keepInput();super.onSaveInstanceState(state);state.putString("mode",mode.name());state.putString("anchor",anchor.toString());state.putString("every",every);state.putString("days",new JSONArray(days).toString());state.putString("error",error);if(calendar!=null&&calendar.showing())state.putBundle("calendar",calendar.state());}
 @Override protected void onDestroy(){if(calendar!=null)calendar.close();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
